INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2744133', 'Battle of Pagan', 'The Battle of Pagan was fought in 1287 between the Yuan dynasty of China and the Pagan Kingdom of Burma. Although the Mongol advance was halted, the war ended the Pagan Kingdom as a polity, which disintegrated into several small kingdoms.', 1287, NULL, NULL, NULL, NULL, NULL, 'year', '1287', 37, 'https://en.wikipedia.org/wiki/Battle_of_Pagan'),
  ('Q16933803', 'Second Mongol invasion of Burma', 'The second Mongol invasion of Burma by the Yuan dynasty under Temür Khan was repulsed by the Burmese Myinsaing Kingdom in 1301.', 1301, 4, 6, 1301, 4, 6, 'day', '6 April 1301', 41, 'https://en.wikipedia.org/wiki/Second_Mongol_invasion_of_Burma'),
  ('Q3119006', 'Forty Years'' War', 'The Forty Years'' War (Burmese: အနှစ်လေးဆယ်စစ်; 1385 – 1423; also Ava–Pegu War or the Mon–Burmese War) was a conflict fought between the Burmese-speaking Kingdom of Ava and the Mon-speaking Kingdom of Hanthawaddy. The war was fought during two separate periods: 1385 to 1391, and 1401 to 1424, interrupted by two truces of 1391–1401 and 1403–1408.', 1385, NULL, NULL, 1424, NULL, NULL, 'year', '1385–1424', 43, 'https://en.wikipedia.org/wiki/Forty_Years''_War'),
  ('Q30682205', 'Ming–Mong Mao War', 'The Ming–Mong Mao War (Chinese: 明麓戰爭) was a military conflict waged between the Ming dynasty and the previously subordinate Shan state of Mong Mao based in Luchuan-Pingmian, which encompasses modern Longchuan, Ruili, and the Gaoligong Mountains.', 1386, 1, NULL, 1388, NULL, NULL, 'month', 'January 1386 – 1388', 30, 'https://en.wikipedia.org/wiki/Ming%E2%80%93Mong_Mao_War_(1386%E2%80%931388)'),
  ('Q7828916', 'Toungoo–Hanthawaddy War', 'The Toungoo–Hanthawaddy War (1534–1541) (Burmese: တောင်ငူ–ဟံသာဝတီ စစ် (၁၅၃၄–၁၅၄၁)) was a military conflict between the Toungoo Kingdom, and the Hanthawaddy kingdom and its allies the Prome Kingdom and the Confederation of Shan States that took place in present-day Lower Burma (Myanmar) between 1534 and 1541. In a series of improbable events, the upstart Burmese-speaking kingdom defeated the Mon-speaking Hanthawaddy, the most prosperous and powerful of all post-Pagan kingdoms before the war.', 1534, 11, NULL, NULL, NULL, NULL, 'month', 'November 1534', 30, 'https://en.wikipedia.org/wiki/Toungoo%E2%80%93Hanthawaddy_War'),
  ('Q4204647', '1833 Sumatra earthquake', 'The 1833 Sumatra earthquake occurred on November 25 at about 22:00 local time, with an estimated magnitude in the range of 8.8–9.2 Mw. It caused a large tsunami that flooded the southwestern coast of the island.', 1833, NULL, NULL, NULL, NULL, NULL, 'year', '1833', 41, 'https://en.wikipedia.org/wiki/1833_Sumatra_earthquake'),
  ('Q1209946', 'Third Anglo-Burmese War', 'The Third Anglo-Burmese War (Burmese: တတိယအင်္ဂလိပ်–မြန်မာစစ်, romanized: Tatiya Ingaleik–Myanma Sit), also known as the Third Burma War (7–29 November 1885, with sporadic resistance continuing into 1887), was the final of three wars fought in the 19th century between the Burmese and the British. The war saw the loss of sovereignty of an independent Burma under the Konbaung dynasty, whose rule had already been reduced to the territory known as Upper Burma, the region of Lower Burma having been annexed by the British in 1853, following the Second Anglo-Burmese War.', 1885, NULL, NULL, 1885, 11, 29, 'year', '1885', 64, 'https://en.wikipedia.org/wiki/Third_Anglo-Burmese_War'),
  ('Q2237206', 'Battle of Pegu', 'The Battle of Pegu was an engagement in the Burma campaign in the Second World War. Fought on 6 and 7 March 1942, it concerned the defence of Rangoon (now Yangon) in Burma (now Myanmar).', 1942, 3, 7, NULL, NULL, NULL, 'day', '7 March 1942', 34, 'https://en.wikipedia.org/wiki/Battle_of_Pegu'),
  ('Q2890419', 'Battle of Yenangyaung', 'The Battle of Yenangyaung (Chinese: 仁安羌大捷; pinyin: Rén''ānqiāng Dàjié; lit. ''Great Victory at Yenangyaung'') was fought in Burma (now Myanmar) from 16 to 19 April 1942.', 1942, 4, 19, NULL, NULL, NULL, 'day', '19 April 1942', 39, 'https://en.wikipedia.org/wiki/Battle_of_Yenangyaung'),
  ('Q7359741', 'Rohingya conflict', 'The Rohingya conflict is an ongoing conflict in the northern part of Rakhine State, Myanmar (formerly known as Arakan, Burma), characterised by sectarian violence between the Rohingya Muslim and Rakhine Buddhist communities, a military crackdown on Rohingya civilians by Myanmar''s security forces, and militant attacks by Rohingya insurgents in Buthidaung, Maungdaw, and Rathedaung Townships, which border Bangladesh. The conflict arises chiefly from the religious and social differentiation between the Rakhine Buddhists and Rohingya Muslims.', 1942, NULL, NULL, NULL, NULL, NULL, 'year', '1942', 55, 'https://en.wikipedia.org/wiki/Rohingya_conflict'),
  ('Q10396694', 'Battle of Yunnan-Burma Road', 'Battle of Yunnan-Burma Road (18 March – 24 May 1942; Chinese: 滇緬路戰役) was the name of the Chinese intervention to aid their British allies in the 1942 Burma Campaign. Its forces were composed of the Fifth, Sixth and Sixty-sixth Army under the command of the Chinese Expeditionary Force in Burma, commanded by Lt.', 1942, 6, NULL, 1942, 6, NULL, 'month', 'June 1942', 39, 'https://en.wikipedia.org/wiki/Battle_of_the_Yunnan%E2%80%93Burma_Road'),
  ('Q19840798', 'Siege of Myitkyina', 'The siege of Myitkyina was an engagement during the Burma campaign of World War II. The Allied victory was part of the larger Battle of Northern Burma and Western Yunnan which succeeded in opening the Ledo Road.', 1944, 5, 17, 1944, 8, 3, 'day', '17 May 1944 – 3 August 1944', 41, 'https://en.wikipedia.org/wiki/Siege_of_Myitkyina'),
  ('Q96373265', 'Battle of Mogaung', 'The Battle of Mogaung was a series of engagements that was fought in the Burma Campaign of World War II between 6 and 26 June 1944 at the Burmese town of Mogaung. In brutal fighting, the 77th ''Chindit'' Brigade under Brigadier Michael Calvert, later assisted by Chinese forces of Generalissimo Chiang Kai-shek, fought for and captured the town from the occupying forces of Imperial Japan.', 1944, 6, 4, 1944, 6, 27, 'day', '4 June 1944 – 27 June 1944', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mogaung'),
  ('Q15232829', 'Kalagong massacre', 'On 7 July 1945, the Kalagon massacre was committed against inhabitants of Kalagon, Burma (present-day Myanmar), by members of the 3rd Battalion, 215th Regiment and the OC Moulmein Kempeitai of the Imperial Japanese Army. These units had been ordered by Major General Seiei Yamamoto, chief of staff of the 33rd Army, to sweep the area for guerrillas reportedly teamed with British paratroopers.', 1945, 7, 7, NULL, NULL, NULL, 'day', '7 July 1945', 37, 'https://en.wikipedia.org/wiki/Kalagon_massacre'),
  ('Q13076194', 'Burmese Declaration of Independence', 'The Burmese Declaration of Independence (Burmese: လွတ်လပ်ရေးကြေညာစာတမ်း) was officially promulgated on 4 January 1948, as a result of the Burma Independence Act 1947, which brought to an end British rule in Burma (now known as Myanmar) that lasted for six decades. The date is now celebrated as Independence Day, a national gazetted holiday.', 1948, 1, 4, NULL, NULL, NULL, 'day', '4 January 1948', 37, 'https://en.wikipedia.org/wiki/Burmese_Declaration_of_Independence'),
  ('Q2652686', 'Kachin conflict', 'The Kachin conflict or the Kachin War is one of the multiple conflicts which are collectively referred to as the internal conflict in Myanmar. Kachin insurgents have been fighting against the Tatmadaw (Myanmar Armed Forces) since 1961, with only one major ceasefire being brokered between them, which lasted from 1994 to 2011, a total of 17 years.', 1961, 2, 5, NULL, NULL, NULL, 'day', '5 February 1961', 48, 'https://en.wikipedia.org/wiki/Kachin_conflict'),
  ('Q4350095', '1962 Burmese coup d''état', 'The 1962 Burmese coup d''état marked the beginning of one-party rule in Burma (Myanmar) and the political dominance of the military in Burmese politics. In the 2 March 1962 coup, the military replaced the civilian AFPFL-government headed by Prime Minister U Nu with the Union Revolutionary Council Chaired by General Ne Win.', 1962, 3, 2, NULL, NULL, NULL, 'day', '2 March 1962', 53, 'https://en.wikipedia.org/wiki/1962_Burmese_coup_d''%C3%A9tat'),
  ('Q274365', '8888 Uprising', 'The 8888 Uprising, also known as the 1988 Uprising, was a series of nationwide protests, marches, and riots in Burma (present-day Myanmar) that peaked in August 1988. Key events occurred on 8 August 1988 and therefore it is commonly known as the "8888 Uprising".', 1988, 3, NULL, 1988, 9, NULL, 'month', 'March 1988 – September 1988', 63, 'https://en.wikipedia.org/wiki/8888_Uprising'),
  ('Q5260602', 'Depayin massacre', 'The Depayin massacre (Burmese: ဒီပဲယင်း လူသတ်မှု) occurred on 30 May 2003 in Tabayin (Depayin), a town in Myanmar''s Sagaing Division (now Sagaing Region), when at least 70 people associated with the National League for Democracy were killed by a government-sponsored mob. In an April 2012 interview, Khin Nyunt, formerly the country''s prime minister, claimed that he personally intervened to save Aung San Suu Kyi''s life during the massacre, by mobilising his men to bring her to a safe location at a nearby army cantonment.', 2003, 5, 30, NULL, NULL, NULL, 'day', '30 May 2003', 41, 'https://en.wikipedia.org/wiki/Depayin_massacre'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q843962', 'Saffron Revolution', 'The Saffron Revolution (Burmese: ရွှေဝါရောင်တော်လှန်ရေး, romanized: Shwaywarraung Tawlhaanrayy; [sw̥èi wà jàʊɰ̃ tɔ̀ l̥àɰ̃ jéi]) was a series of economic and political protests and demonstrations that took place during August, September and October 2007 in Myanmar. The protests were triggered by the decision of the national military government to remove subsidies on the sales prices of fuel.', 2007, 8, 15, NULL, NULL, NULL, 'day', '15 August 2007', 67, 'https://en.wikipedia.org/wiki/Saffron_Revolution'),
  ('Q150495', '2011 Tarlay earthquake', 'The 2011 Shan earthquake occurred on 24 March in Shan State, Myanmar. The earthquake measured Mw 6.8 and had an epicenter northwest of the border between Myanmar, Thailand and Laos.', 2011, 3, 24, NULL, NULL, NULL, 'day', '24 March 2011', 61, 'https://en.wikipedia.org/wiki/2011_Shan_earthquake'),
  ('Q576390', '2011 Yunnan earthquake', 'The 2011 Yunnan earthquake was a 5.4 magnitude earthquake that occurred on 10 March 2011 at 12:58 CST, with its epicenter in Yingjiang County, Yunnan, People''s Republic of China, near the Burmese border. A total of 26 people died and 313 were injured with 133 in serious condition.', 2011, 3, 10, NULL, NULL, NULL, 'day', '10 March 2011', 53, 'https://en.wikipedia.org/wiki/2011_Yunnan_earthquake'),
  ('Q24932', '2012 Shwebo earthquake', 'The 2012 Shwebo earthquake occurred at 07:42 local time (01:12 UTC) on 11 November in Myanmar. It had a magnitude of 6.8 on the moment magnitude scale and a maximum perceived intensity of VII (Very strong) on the Mercalli intensity scale.', 2012, 11, 11, NULL, NULL, NULL, 'day', '11 November 2012', 39, 'https://en.wikipedia.org/wiki/2012_Shwebo_earthquake'),
  ('Q23809830', '2016 Myanmar earthquake', 'A magnitude 6.9 earthquake struck Myanmar 135 km (84 mi) north-west of Mandalay on April 13 with a maximum Mercalli intensity of VI (Strong). It struck at 8:25 pm local time (13:55 UTC), and was centered in an isolated area.', 2016, 4, 13, NULL, NULL, NULL, 'day', '13 April 2016', 50, 'https://en.wikipedia.org/wiki/2016_Kani_earthquake'),
  ('Q26690160', '2016 Chauk earthquake', 'A magnitude 6.8 earthquake struck Myanmar 25 km (16 mi) west of Chauk on 24 August 2016 with a maximum Mercalli intensity of VI (Strong). It struck at 5:04 pm local time (10:34 UTC), and was centered in an isolated area.', 2016, 8, 24, NULL, NULL, NULL, 'day', '24 August 2016', 52, 'https://en.wikipedia.org/wiki/2016_Chauk_earthquake'),
  ('Q28136551', 'Rohingya genocide', 'The Rohingya genocide is a series of ongoing persecutions and killings of the Muslim Rohingya people by the Tatmadaw (armed forces of Myanmar). The genocide has consisted of two phases to date: the first was a military crackdown that occurred from October 2016 to January 2017, and the second has been occurring since August 2017.', 2016, 10, 9, NULL, NULL, NULL, 'day', '9 October 2016', 68, 'https://en.wikipedia.org/wiki/Rohingya_genocide'),
  ('Q29025615', 'conflict in Rakhine State', 'Violent clashes have been ongoing in the northern part of Myanmar''s Rakhine State since October 2016. Insurgent attacks by the Arakan Rohingya Salvation Army (ARSA) have led to sectarian violence perpetrated by Myanmar''s military and the local Buddhist population against predominantly Muslim Rohingya civilians.', 2016, 10, 9, NULL, NULL, NULL, 'day', '9 October 2016', 47, 'https://en.wikipedia.org/wiki/Conflict_in_Rakhine_State_(2016%E2%80%93present)'),
  ('Q30149289', '2017 Myanmar Air Force Shaanxi Y-8 crash', 'On 7 June 2017, a Shaanxi Y-8 aircraft of the Myanmar Air Force crashed on a flight from Myeik to Yangon, killing all 122 people on board. Debris from the aircraft was found in the Andaman Sea, 118 nautical miles (218 km) off Dawei by Myanmar Navy ships.', 2017, 6, 7, NULL, NULL, NULL, 'day', '7 June 2017', 53, 'https://en.wikipedia.org/wiki/2017_Myanmar_Air_Force_Shaanxi_Y-8_crash'),
  ('Q41980738', 'Kha Maung Seik massacre', 'On 25 August 2017, Muslim insurgents from the Arakan Rohingya Salvation Army (ARSA) attacked Hindu villages in a cluster known as Kha Maung Seik in the northern Maungdaw District of Rakhine State in Myanmar and massacred 99 Bengali Hindu villagers. A month later, the Myanmar Army discovered mass graves containing the corpses of 45 Hindus, most of whom were women and children.', 2017, 8, 25, NULL, NULL, NULL, 'day', '25 August 2017', 37, 'https://en.wikipedia.org/wiki/Kha_Maung_Seik_massacre'),
  ('Q48734865', 'Inn Din massacre', 'The Inn Din massacre was a mass execution of Rohingyas by the Myanmar Army and armed Rakhine locals in the village of Inn Din, in Rakhine State, Myanmar on 2 September 2017. The victims were accused of being members of the Arakan Rohingya Salvation Army (ARSA) by authorities.', 2017, NULL, NULL, NULL, NULL, NULL, 'year', '2017', 39, 'https://en.wikipedia.org/wiki/Inn_Din_massacre'),
  ('Q105180889', '2021 Myanmar coup d''état', 'A coup d''état in Myanmar began on the morning of 1 February 2021, when democratically elected members of the country''s ruling party, the National League for Democracy (NLD), were deposed by the Tatmadaw, Myanmar''s military, which then vested power in a military junta. Acting President of Myanmar Myint Swe proclaimed a year-long state of emergency and declared power had been transferred to Commander-in-Chief of Defence Services Senior General Min Aung Hlaing.', 2021, 2, 1, 2021, 2, 1, 'day', '1 February 2021', 78, 'https://en.wikipedia.org/wiki/2021_Myanmar_coup_d''%C3%A9tat'),
  ('Q105367670', '2021–present Myanmar protests', 'Protests in Myanmar, known locally as the Spring Revolution (Burmese: နွေဦးတော်လှန်ရေး, Burmese pronunciation: [nwè.ú.tɔ̀.l̥àɰ̃.jé]), began in early 2021 in opposition to the coup d''état on 1 February, staged by Min Aung Hlaing, the commander-in-chief of the country''s armed forces, the Tatmadaw. As of 23 June 2022, at least 2000 protesters had been killed, 14,000 arrested and 700,000 displaced by the military junta.', 2021, 2, 2, NULL, NULL, NULL, 'day', '2 February 2021', 65, 'https://en.wikipedia.org/wiki/Myanmar_protests_(2021%E2%80%93present)'),
  ('Q110613097', 'Myanmar Civil War', 'The Myanmar civil war began following the military coup on 1 February 2021. The seizure of power triggered mass anti-coup demonstrations and a violent crackdown by the Tatmadaw (Myanmar armed forces), which significantly escalated the country''s longstanding insurgencies.', 2021, 5, 5, NULL, NULL, NULL, 'day', '5 May 2021', 70, 'https://en.wikipedia.org/wiki/Myanmar_civil_war_(2021%E2%80%93present)'),
  ('Q116944530', 'Bago massacre', 'The Bago massacre was a mass killing of civilians on Friday, 9 April 2021, in the city of Bago, Myanmar. During the massacre, Myanmar Army troops and Myanmar Police Force officers killed at least eighty-two civilians.', 2021, 4, 9, NULL, NULL, NULL, 'day', '9 April 2021', 41, 'https://en.wikipedia.org/wiki/Bago_massacre'),
  ('Q116958167', 'Hlaingthaya massacre', 'The Hlaingthaya massacre was a mass killing of civilians on 14 March 2021, in Hlaingthaya Township (also spelt Hlaing Tharyar and Hlinethaya), Yangon, Myanmar. During the massacre, Myanmar Army troops and Myanmar Police Force officers killed at least sixty-five individuals.', 2021, 3, 14, NULL, NULL, NULL, 'day', '14 March 2021', 34, 'https://en.wikipedia.org/wiki/Hlaingthaya_massacre'),
  ('Q114841701', 'Hpakant massacre', 'On the night of 23 October 2022, the Myanmar Air Force launched a series of airstrikes in Hpakant Township, Kachin State, Northern Myanmar. The targeted area was within the territory of the Kachin Independence Organization''s 9th Brigade in the Anangpa (အနန့်ပါ) area.', 2022, 10, 23, NULL, NULL, NULL, 'day', '23 October 2022', 43, 'https://en.wikipedia.org/wiki/Hpakant_massacre'),
  ('Q117595454', 'Pazigyi massacre', 'On 11 April 2023, the Myanmar Air Force massacred at least 165 people in the village of Pazigyi, Kantbalu Township, which is located 92 miles (148 km) west of Mandalay, Myanmar''s second largest city. The air force used fighter jets and helicopters to attack a large crowd of people gathering for the opening of a local office of an opposition movement.', 2023, 4, 11, NULL, NULL, NULL, 'day', '11 April 2023', 52, 'https://en.wikipedia.org/wiki/Pazigyi_massacre'),
  ('Q124254474', 'Battle of Laukkai', 'The Battle of Laukkai was a military offensive conducted by the Myanmar National Democratic Alliance Army (MNDAA) encircling and capturing Laukkai, the capital of the Kokang Self-Administered Zone (Kokang SAZ) in northeastern Myanmar. The battle was part of the larger Operation 1027, a joint military operation conducted by the Three Brotherhood Alliance coalition of three ethnic armed organisations and part of the overall renewed civil war in Myanmar.', 2023, 11, 15, 2024, 1, 5, 'day', '15 November 2023 – 5 January 2024', 34, 'https://en.wikipedia.org/wiki/Battle_of_Laukkai'),
  ('Q133574091', '2025 Myanmar earthquake', 'On 28 March 2025, at 12:50:52 MMT (06:20:52 UTC), a moment magnitude (Mw) 7.7–7.9 earthquake struck the Sagaing Region of Myanmar, with an epicenter close to Mandalay, the country''s second-largest city. The shaking caused by this strike-slip shock reached a maximum Modified Mercalli intensity of X (Extreme).', 2025, 3, 28, NULL, NULL, NULL, 'day', '28 March 2025', 81, 'https://en.wikipedia.org/wiki/2025_Myanmar_earthquake'),
  ('Q139997516', '2026 Namhkam Township explosion', 'On 31 May 2026, a major explosion occurred at a building storing explosives used for mining in Namhkam Township, Shan State, Myanmar. The explosion occurred in territory controlled by the Ta''ang National Liberation Army (TNLA), one of the rebel groups fighting in the country''s ongoing civil war.', 2026, 5, 31, NULL, NULL, NULL, 'day', '31 May 2026', 41, 'https://en.wikipedia.org/wiki/2026_Namhkam_Township_explosion');
